effect.shader:
float r2(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453123); }
float vnoise2(vec2 p){
vec2 i=floor(p), f=fract(p);
vec2 u=f*f*(3.0-2.0*f);
float n00=r2(i);
float n10=r2(i+vec2(1.0,0.0));
float n01=r2(i+vec2(0.0,1.0));
float n11=r2(i+vec2(1.0,1.0));
float nx0=mix(n00,n10,u.x);
float nx1=mix(n01,n11,u.x);
return mix(nx0,nx1,u.y);
}
vec3 firePalette(float w){
vec3 c = vec3(0.0);
c += vec3(1.0, 0.15, 0.05) * pow(w, 0.7);
c += vec3(1.0, 0.55, 0.10) * pow(w, 1.2);
c += vec3(1.0, 0.95, 0.85) * pow(w, 2.2);
return clamp(c, 0.0, 1.0);
}
float starShape(vec2 uv, float r, float points, float inner){
float a = atan(uv.y, uv.x);
float d = length(uv);
float pi = 3.141592653589793;
float p = points;
float seg = (2.0*pi/p);
float k = cos(floor(0.5 + a/seg)*seg - a) * inner + 1.0;
return d - r * k;
}
float plasmaLayer(vec2 uv, float scale, float speed, float shift){
float t = acTime * timeSpeed;
return sin(uv.x*scale + t*speed + shift) * 0.01 +
cos(uv.y*scale - t*speed*1.3 + shift*1.7) * 0.01;
}
vec3 palette(float x){
float t = acTime * timeSpeed;
return 0.5 + 0.5 * cos(6.2831853 * (vec3(0.25,0.4,0.6) + t + x));
}
void main(){
vec2 fragCoord = acScreenNorm * acScreenSize;
vec2 iResolution = acScreenSize;
vec2 uv = (fragCoord - 0.5*iResolution.xy) / max(iResolution.y, 1.0);
float star = starShape(uv, starRadius, float(points), inner);
float distort = 0.0;
distort += plasmaLayer(uv, scale1, speed1, 0.0);
distort += plasmaLayer(uv, scale2, speed2, 2.0);
distort += plasmaLayer(uv, scale3, speed3, 5.0);
vec2 pixelSize = vec2(1.0) / max(iResolution, vec2(1.0));
vec4 blurMid = texture2DCv(blurBuf.texture, acScreenNorm);
vec4 blurUp = texture2DCv(blurBuf.texture, acScreenNorm + pixelSize*vec2(0.0,-4.0));
vec4 blurLeft = texture2DCv(blurBuf.texture, acScreenNorm + pixelSize*vec2(-4.0,0.0));
float dx = blurMid.a - blurLeft.a;
float dy = blurMid.a - blurUp.a;
vec2 gradN = normalize(vec2(dx, dy));
float p = blurMid.a;
float prog = clamp(burnProgress + (autoAnimate ? acTime * burnRate : 0.0), 0.0, 1.0);
float dist = mix(0.95, 0.05, prog);
dist += (0.5 - (distance * 0.4 + 0.5)) * 0.1;
float ringW = max(burnWidth, 0.001);
float n = vnoise2(acScreenNorm*edgeNoiseScale + vec2(seed*7.123, seed*3.71 + acTime*0.05));
float distN = dist + (edgeNoiseAmt * (n - 0.5)) * ringW * 1.5;
float ringWFeather = ringW * mix(0.5, 2.0, clamp(smoothFeather,0.0,1.0));
float core = 1.0 - smoothstep(0.0, ringWFeather, abs(p - distN));
float hardnessExp = mix(6.0, 1.0, clamp(burnHardness,0.0,1.0));
float ringMask = pow(clamp(core, 0.0, 1.0), hardnessExp);
if(edgeSide==0){
ringMask *= (1.0 - step(distN, p));
} else if(edgeSide==1){
ringMask *= step(distN, p);
}
float heatN = (vnoise2(acScreenNorm*heatScale + vec2(seed*1.23, 17.31 + acTime*0.2)) - 0.5);
vec2 heatDir = normalize(gradN + vec2(1e-6));
vec2 sampleUV = acScreenNorm + heatDir * heatStrength * ringMask * (0.5 + heatN);
vec4 texColor = texture2DCv(inputImg.texture, sampleUV);
float edgeProx = saturate(1.0 - abs(p - distN) / ringW);
vec3 fireCol = firePalette(edgeProx);
vec3 rainbowCol = palette(star*6.0);
vec3 emissive = (paletteMode==0 ? fireCol : rainbowCol);
emissive = mix(emissive, vec3(1.0), clamp(whiteHot,0.0,2.0) * pow(edgeProx, 2.0));
emissive *= tintColor.rgb;
float dNorm = abs(p - distN) / max(ringW, 1e-4);
float glowArg = pow(dNorm, clamp(glowFeather,0.5,3.0));
vec3 glow = emissive * glowIntensity * exp(-glowFalloff * glowArg);
float blobN = vnoise2(acScreenNorm*(edgeNoiseScale*0.7) + vec2(seed*2.17, acTime*0.12));
float hot = saturate((edgeProx + (blobN-0.5)*0.6 - hotspotThresh) * (2.0 + hotspotGain));
glow *= (1.0 + pow(hot, hotspotGain) * 1.5);
float auraDist = abs(p - (distN + ringW*1.15)) / max(ringW*2.2, 1e-4);
vec3 aura = emissive * auraIntensity * exp(-auraFalloff * auraDist);
vec3 finalColor = glow + aura;
float edgeMask = ringMask;
vec4 masked = vec4(finalColor, 1.0) * edgeMask;
if(hideBase){
gl_FragColor = masked;
return;
}
float cutWidth = ringW * (1.0 + clamp(cutFeather,0.0,1.0)*1.5);
float cutMask = smoothstep(distN, distN + cutWidth, p) * edgeMask;
texColor.a *= (1.0 - cutMask * cutAmount);
vec4 outColor;
if(blendMode==1){
outColor = vec4((texColor.rgb/texColor.a) * masked.rgb, 1.0) * texColor.a;
} else if(blendMode==2){
outColor = vec4(1.0 - (1.0 - (texColor.rgb/texColor.a)) * (1.0 - masked.rgb), 1.0) * texColor.a;
} else {
outColor = masked * texColor.a;
outColor = texColor*(1.0 - outColor.a) + outColor;
}
gl_FragColor = mix(texColor * fill, outColor, alpha);
}
